This preserves the existing one-shot CLI and MCP behavior. If Warlock is absent or stopped, the first query performs exactly the current bounded preparation. If Warlock is healthy, repository registration and later events warm state before the first query that needs it.

Lexicon compatibility

Retain `lexicon demon` as an independently usable optional mode. In a Warlock-managed repository, avoid running both it and a Warlock watcher by default. Warlock can invoke Grimoire's bounded refresh path; Grimoire invokes one-shot `lexicon scan`, whose private mirror still computes the actual incremental change set. This preserves Lexicon's standalone…"}},{"handle":"g2_sede12587d3657b7c1c3c33dde5627d9542c4c2e189e1daf4f27d5ac48893e3cd_8e935950170882e4","evidence":{"path":"evaluation/results/agent-benchmark-v2/grimoire-state-maintenance-ownership/plain.stdout.txt","start_line":93,"end_line":112}},{"handle":"g2_s210e1a245a9012444a5707fe167b1d4a1fb2b80d1210d40f37883d7d93e55d6a_769862c1adf6e8ac","evidence":{"path":"evaluation/results/agent-benchmark-v2/grimoire-state-maintenance-ownership/plain.stdout.txt","start_line":45,"end_line":91}},{"handle":"g2_s490c00d729ff0e6f5ec39fc3c753fb6794691811b928640bb70128f7c30b6565_dab52ffd5688db43","evidence":{"path":"evaluation/results/agent-benchmark-v2/grimoire-state-maintenance-ownership/grimoire.stdout.txt","start_line":97,"end_line":135}},{"handle":"g2_s4eab6735c97f9a5c2fc166129f896e789409522b0300f7ab8014c94764141c0c_7b3ab55407d5f5d3","evidence":{"path":"evaluation/results/agent-benchmark-v2/grimoire-state-maintenance-ownership/grimoire.stdout.txt","start_line":49,"end_line":95}},{"handle":"g2_s76ab2c376e309fac717afe1e167233242b181619e0dd19b12499913b12f2e785_be1140ba3ea0f445","evidence":{"path":"evaluation/agent_benchmark_tasks.v2.json","start_line":97,"end_line":117}},{"handle":"g2_s23c3717632120754471bd662b9669eaca389d530ccc7f2a5e9c93332abb1d5df_832d38cefa751cb7","evidence":{"path":"evaluation/retrieval/grimoire.json","start_line":596,"end_line":596}},{"handle":"g2_sfe66d7a2d0a4d7b0e4aeb1a22900f7d5cd749aa768d27543cf7b9a2f33b75295_0daeec37ad7f6783","evidence":{"path":"arcana/src/repository/repository_snapshot.rs","start_line":10,"start_column":1,"end_line":13,"end_column":3,"text":"use super::repository_snapshot_validation::{
    checksum, compare, read_verified, repository_identity, repository_identity_from_checksum, text,
    validate_components, validate_precompiled_components, write_immutable,
};"}},{"handle":"g2_s663b2098d0b1a13eb1bcda8f6dce28d6f31958b8cec79879a92998b5715cbbbf_53e27558e8e05ff9","evidence":{"path":"arcana/src/repository/repository_snapshot.rs","start_line":279,"start_column":1,"end_line":303,"end_column":2,"text":"pub fn derive_repository_snapshot_id(
    repository_id: u64,
    graph_snapshot_id: u64,
    catalogue_checksum: u64,
    unresolved_checksum: u64,
    facts_checksum: u64,
    adapter_name: &str,
    adapter_version: &str,
) -> u64 {
    let mut hasher = StableHasher::new();
    hasher.update(b"arcana-repository-snapshot-v1");
    for value in [
        repository_id,
        graph_snapshot_id,
        catalogue_checksum,
        unresolved_checksum,
        facts_checksum,
    ] {
        hasher.update(&value.to_le_bytes());
    }
    hasher.update(adapter_name.as_bytes());
    hasher.update(&[0]);
    hasher.update(adapter_version.as_bytes());
    hasher.finish()
}"}},{"handle":"g2_s8b9bbfafd8cdca5ba60b858ca589182de457d9d1c25f7537b6620f09b4e6848f_207d1a94e13bf972","evidence":{"path":"arcana/src/repository/repository_snapshot_error.rs","start_line":19,"start_column":5,"end_line":19,"end_column":39}},{"handle":"g2_s9d04d0a151a06f797eff54f8a31d694309ffb05d3494c48612fc99a269321128_a171cd802f5e3e37","evidence":{"path":"arcana/src/repository/repository_snapshot_error.rs","start_line":25,"start_column":5,"end_line":28,"end_column":6}},{"handle":"g2_sa0c50b94ee42f97e9e6485d144315a8ae600a19574958dff84f0e47a6e04477b_6684924b3aa50818","evidence":{"path":"arcana/src/repository/repository_snapshot_tests.rs","start_line":44,"start_column":1,"end_line":102,"end_column":2}},{"handle":"g2_s58b0cda19d66b34c3a1487aa5dd889578ffda882323e7f766ceb190cf44a5a92_dabeddcee756b123","evidence":{"path":"arcana/src/repository/repository_snapshot_tests.rs","start_line":104,"start_column":1,"end_line":138,"end_column":2}},{"handle":"g2_sdfc1dc5b773910f30b1a5f3877bed423393878f62e178b97b197dfae1ba1bd2e_a8219ac93a4613ed","evidence":{"path":"arcana/src/repository/repository_snapshot_validation.rs","start_line":56,"start_column":1,"end_line":95,"end_column":2}},{"handle":"g2_s092f31cebd4ea28a72f6596b1c4f9e42bd87fe4d67ec77faa297f6666b66ad2b_8066ff93fb134e5d","evidence":{"path":"arcana/src/repository/repository_snapshot_validation.rs","start_line":13,"start_column":1,"end_line":40,"end_column":2}}],"new_documents":[{"handle":"g2_d4b2af71ac7ec337b7e04d2590e1a35bdef2948b6b06e9303df43aa9cad87c2ff_0398cb0ee2a69f21","evidence":{"uri":"docs/planning/roadmap.md","title":"Prepared-state maintenance","content":"## Prepared-state maintenance

