45:func (s *Scanner) notifyConsumers(ctx context.Context, report Report, scanErr error) (Report, error) {
46:	if scanErr != nil {
47:		return report, scanErr
48:	}
49:	if err := consumer.Run(ctx, s.Repository, s.Store.Root, report.SnapshotID, s.Output); err != nil {
50:		return report, err
51:	}
52:	return report, nil
53:}
